<div class="reseller-shell reseller-portal"><div class="container"><div class="reseller-page-toolbar no-print"><div><span class="reseller-kicker">Detail nota</span><h1><?= esc($quote['quote_number']) ?></h1></div><div class="reseller-quick-actions"><button class="btn-reseller-secondary" type="button" onclick="window.print()"><i class="fas fa-print"></i> Cetak / Simpan PDF</button><a class="btn-reseller-primary" href="<?= base_url('reseller/quotes') ?>">Kembali</a></div></div><?php if ($success = session()->getFlashdata('success')): ?><div class="reseller-alert success no-print"><p><?= esc($success) ?></p></div><?php endif; ?><article class="reseller-invoice"><header><div><span class="invoice-brand">S</span><div><strong><?= esc($reseller['business_name']) ?></strong><small><?= esc($reseller['whatsapp']) ?><?= $reseller['city'] ? ' · ' . esc($reseller['city']) : '' ?></small></div></div><div><span>NOTA / PENAWARAN</span><strong><?= esc($quote['quote_number']) ?></strong><small><?= date('d F Y', strtotime($quote['created_at'])) ?></small></div></header><section class="invoice-customer"><div><span>Kepada</span><strong><?= esc($quote['customer_name']) ?></strong><small><?= esc($quote['customer_phone']) ?></small><small><?= nl2br(esc($quote['customer_address'])) ?></small></div><div class="no-print"><span>Status</span><strong><?= esc(ucfirst($quote['status'])) ?></strong></div></section><div class="table-responsive"><table><thead><tr><th>Produk</th><th>Spesifikasi</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= esc($item['product_name']) ?></strong><small><?= esc($item['model_name']) ?></small></td><td><?= esc(implode(' · ', array_filter([$item['material'], $item['color'], $item['size']]))) ?></td><td><?= (int) $item['quantity'] ?> pcs</td><td>Rp <?= number_format($item['selling_price'], 0, ',', '.') ?></td><td>Rp <?= number_format($item['subtotal'], 0, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table></div><footer><div><span>Catatan</span><p><?= nl2br(esc($quote['notes'] ?: 'Harga dan jadwal produksi mengikuti konfirmasi akhir.')) ?></p></div><div class="invoice-total"><span>Total</span><strong>Rp <?= number_format($quote['selling_total'], 0, ',', '.') ?></strong></div></footer></article><section class="reseller-margin reseller-private no-print"><div><span>Biaya dasar Sagara</span><strong>Rp <?= number_format($quote['base_total'], 0, ',', '.') ?></strong></div><div><span>Estimasi margin Anda</span><strong>Rp <?= number_format($quote['selling_total'] - $quote['base_total'], 0, ',', '.') ?></strong></div><form action="<?= base_url('reseller/quotes/' . $quote['id'] . '/status') ?>" method="post"><?= csrf_field() ?><label for="quote-status">Status nota</label><select id="quote-status" name="status"><?php foreach (['draft' => 'Draft', 'sent' => 'Sudah dikirim', 'accepted' => 'Disetujui customer', 'cancelled' => 'Dibatalkan'] as $value => $label): ?><option value="<?= $value ?>" <?= $quote['status'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><button class="btn-reseller-secondary">Simpan</button></form></section></div></div>
